import time
import logging
import socket
import traceback
from abc import ABCMeta, abstractmethod
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.exceptions import ReadOutputTimout, SendCommandFailure, UnexpectedReadOutputFailure


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AuthenticatableRunner(ManagedObject, metaclass=ABCMeta):

    def __init__(self, authenticationsteps=None, **kwargs):
        """
        Create an authenticatable runner.

        :param AuthenticationOperation authenticationsteps: authentication steps.
        :return AuthenticatableRunner: authenticatable runner object.
        """
        super(AuthenticatableRunner, self).__init__(**kwargs)
        self._authenticationsteps = authenticationsteps if authenticationsteps else []

    def _setup(self):
        self._authenticate()

    def _authenticate(self):
        for step in self._authenticationsteps:
            step.run(self)

    @abstractmethod
    def execute(self, command, timeout=1):
        pass

    @abstractmethod
    def send_command(self, command):
        pass

    def read_until(self, expectstr, timeout):
        if not expectstr:
            return ""

        output = ""
        end = time.time() + timeout
        while time.time() < end:
            output += self.read_output()
            if expectstr in output:
                return output
            time.sleep(1)

        raise ReadOutputTimout("'{}' not contain '{}'".format(output, expectstr))

    @abstractmethod
    def read_output(self):
        pass

    @abstractmethod
    def _teardown(self):
        pass


class AuthenticatableShell(AuthenticatableRunner):

    _READ_BYTE_SIZE = 65535

    def __init__(self, ssh_connection, command_postfix="\r", **kwargs):
        """
        Create an authenticatable shell runner.

        :param SshConnection ssh_connection: ssh connection object.
        :param str command_postfix: specified command postfix.
        :return AuthenticatableShell: authenticatable shell runner object.
        """
        super(AuthenticatableShell, self).__init__(**kwargs)
        self._ssh_connection = ssh_connection
        self._command_postfix = command_postfix
        self._session = None

    def _setup(self):
        self._session = self._ssh_connection.invoke_shell()
        super(AuthenticatableShell, self)._setup()

    def execute(self, command, timeout=1):
        self.send_command(command)
        time.sleep(timeout)
        return self.read_output()

    def send_command(self, command):
        logger.debug("send command: '{}'".format(command))
        sent_size = self._session.send("{}{}".format(command, self._command_postfix))
        if not sent_size:
            raise SendCommandFailure("{}".format(command))

    @staticmethod
    def _convert_bytes_to_str(data, encoding):
        if isinstance(data, bytes):
            data = data.decode(encoding=encoding)
        return data

    def _recv_data(self, encoding):
        data = self._session.recv(self._READ_BYTE_SIZE)
        return self._convert_bytes_to_str(data, encoding)

    def _recv_stderr_data(self, encoding):
        stderr_data = self._session.recv_stderr(self._READ_BYTE_SIZE)
        return self._convert_bytes_to_str(stderr_data, encoding)

    def read_output(self, encoding='utf-8'):
        output = ""
        if self._session.recv_ready():
            output += self._recv_data(encoding)

        if self._session.recv_stderr_ready():
            output += self._recv_stderr_data(encoding)

        logger.debug("output: '{}'".format(output))
        return output

    def read_output_until(self, expectstr, encoding='utf-8'):
        if not expectstr:
            return ""

        output = ""
        default_timeout = self._session.gettimeout()
        self._session.settimeout(1)
        try:
            while True:
                try:
                    output += self._recv_data(encoding)
                    if expectstr in output:
                        break
                except socket.timeout as err:
                    raise ReadOutputTimout("'{}' contains no '{}' for {}".format(output, expectstr, err))
                except Exception as unexpected_err:
                    logger.error("exception is {}, traceback is {}".format(unexpected_err, traceback.format_exc()))
                    raise UnexpectedReadOutputFailure(unexpected_err)
            return output
        finally:
            self._session.settimeout(default_timeout)

    def _teardown(self):
        self._session.close()


class AuthenticationOperation(object):

    def __init__(self, inputstr, expectstr="", read_timeout=10):
        """
        Create an Authentication operation.

        :param str inputstr: input string after expected string occurs.
        :param str expectstr: expect output string.
        :return AuthenticationOperation: authentication operation object.
        """
        self._inputstr = inputstr
        self._expectstr = expectstr
        self._read_timeout = read_timeout

    def run(self, runner):
        runner.read_until(self._expectstr, self._read_timeout)
        return runner.send_command(self._inputstr)
